type Disponibilidad={fecha:string;cancha:Cancha;disponibleEseDia:boolean;horarios:Horario[]};type PanoramaDisponibilidad={fecha:string;canchas:Disponibilidad[]};type AlternativaDisponibilidad={cancha:Cancha;disponibleEseDia:boolean;horarios:Horario[];error?:boolean};
