function w2bRenderHorarios(horarios:Horario[],items:AlternativaDisponibilidad[]=[]){const lista=el('listaHorarios');if(!horarios.length){const consultadas=items.filter(x=>!x.error),todasCerradas=consultadas.length>0&&consultadas.every(x=>!x.disponibleEseDia),todasCompletas=consultadas.length>0&&consultadas.every(x=>x.disponibleEseDia&&!x.horarios.length),conAlternativas=items.some(x=>x.horarios.length>0);const titulo=todasCerradas?'El complejo está cerrado este día':todasCompletas?'Las canchas están completas':conAlternativas?'Esta cancha no tiene horarios':'No pudimos encontrar horarios';const texto=todasCerradas?'Elegí otra fecha para consultar la agenda disponible.':todasCompletas?'Probá otra fecha. Los horarios de este día ya fueron ocupados.':conAlternativas?'Elegí otra cancha en el panorama o cambiá la fecha.':'Volvé a consultar otra fecha o intentá nuevamente.';lista.innerHTML='<div class="reserve-empty w2b-empty-smart"><span aria-hidden="true">◷</span><div><strong>'+titulo+'</strong><p>'+texto+'</p></div><div><button type="button" class="w2b-primary" data-w2b-other-date>Elegir otra fecha</button>'+(conAlternativas?'<button type="button" class="w2b-secondary" data-w2b-other-court>Ver canchas disponibles</button>':'')+'</div></div>';lista.querySelector<HTMLButtonElement>('[data-w2b-other-date]')?.addEventListener('click',()=>{paso(1);requestAnimationFrame(()=>el<HTMLButtonElement>('w2calTrigger').focus({preventScroll:true}))});lista.querySelector<HTMLButtonElement>('[data-w2b-other-court]')?.addEventListener('click',()=>el('w2bAvailabilityOverview').scrollIntoView({behavior:movimientoReducidoReserva()?'auto':'smooth',block:'start'}));return}lista.innerHTML=horarios.map(h=>'<button type="button" class="reserve-time '+(estado.horario?.horaInicio===h.horaInicio?'selected':'')+'" data-inicio="'+h.horaInicio+'" aria-pressed="'+(estado.horario?.horaInicio===h.horaInicio)+'"><span class="reserve-time-main"><small>'+w2bFranja(h.horaInicio)+' · Disponible</small><strong>'+hora(h.horaInicio)+' a '+hora(h.horaFin)+'</strong><i>'+(estado.cancha?.duracionMinutos||90)+' minutos</i></span><span class="reserve-time-price"><small>TURNO</small><b>'+moneda(h.precio,estado.complejo?.moneda||'ARS')+'</b><em>Seña '+moneda(h.importeSenia,estado.complejo?.moneda||'ARS')+'</em></span><span class="reserve-time-choice">Elegir '+hora(h.horaInicio)+' →</span></button>').join('');lista.querySelectorAll<HTMLButtonElement>('.reserve-time').forEach(button=>button.addEventListener('click',()=>{estado.horario=horarios.find(h=>h.horaInicio===button.dataset.inicio);lista.querySelectorAll<HTMLButtonElement>('.reserve-time').forEach(x=>{x.classList.remove('selected');x.setAttribute('aria-pressed','false')});button.classList.add('selected');button.setAttribute('aria-pressed','true');actualizarResumen();mostrarDatos()}))}
async function w2bConsultarPanorama(token:number){const matrix=el('w2bAvailabilityMatrix'),summary=el('w2bAvailabilitySummary');matrix.setAttribute('aria-busy','true');matrix.innerHTML='<div class="reserve-loading"><span></span><strong>Comparando canchas…</strong></div>';summary.textContent='Consultando alternativas…';const respuesta=await api<PanoramaDisponibilidad|Disponibilidad>('/disponibilidad/panorama?fecha='+estado.fecha,{forceRefresh:true});if(token!==estado.consulta)return null;const disponibilidades=Array.isArray((respuesta as PanoramaDisponibilidad).canchas)?(respuesta as PanoramaDisponibilidad).canchas:[respuesta as Disponibilidad];const items:AlternativaDisponibilidad[]=estado.canchas.map(cancha=>{const d=disponibilidades.find(x=>x.cancha?.id===cancha.id);return d?{cancha,disponibleEseDia:d.disponibleEseDia,horarios:d.horarios}:{cancha,disponibleEseDia:false,horarios:[],error:true}});w2bRenderAlternativas(items);return items}
el('buscarHorarios').addEventListener('click',async()=>{if(!estado.cancha)return mensaje('Seleccioná una cancha.');actualizarFecha();if(!estado.fecha)return mensaje('Seleccioná una fecha.');const token=++estado.consulta;el('listaHorarios').innerHTML='<div class="reserve-loading"><span></span><strong>Consultando disponibilidad...</strong><p>Estamos revisando la agenda en tiempo real.</p></div>';el('tituloHorarios').innerHTML='<span>Horarios disponibles</span><small><b>'+esc(estado.cancha.nombre)+'</b><i aria-hidden="true">·</i>'+fecha(estado.fecha)+'</small>';paso(2);try{const items=await w2bConsultarPanorama(token);if(!items||token!==estado.consulta)return;const actual=items.find(x=>x.cancha.id===estado.cancha?.id);w2bRenderHorarios(actual?.horarios||[],items);void w2bBuscarFechasAlternativas(items)}catch(e){if(token!==estado.consulta)return;mensaje(e instanceof Error?e.message:'No se pudo consultar la disponibilidad.');paso(1)}});
let w2bFiltroHorario='TODOS';
function w2bActualizarFiltros(){const host=document.getElementById('w2bTimeFilters'),status=document.getElementById('w2bTimeFilterStatus'),tools=document.getElementById('w2bTimeTools'),lista=document.getElementById('listaHorarios');if(!host||!status||!tools||!lista)return;const rows=[...lista.querySelectorAll<HTMLElement>('.reserve-time')];tools.classList.toggle('hidden',rows.length===0);const counts={TODOS:rows.length,'MAÑANA':0,'TARDE':0,'NOCHE':0} as Record<string,number>;rows.forEach(row=>{const label=row.querySelector('.reserve-time-main small')?.textContent||'';const franja=['MAÑANA','TARDE','NOCHE'].find(x=>label.includes(x))||'OTRA';row.dataset.timeBand=franja;if(franja in counts)counts[franja]++;row.classList.remove('recommended');row.querySelector('.w2b-recommended-badge')?.remove()});host.querySelectorAll<HTMLButtonElement>('[data-time-filter]').forEach(button=>{const filter=button.dataset.timeFilter||'TODOS',active=filter===w2bFiltroHorario;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;const count=button.querySelector<HTMLElement>('[data-time-count]');if(count)count.textContent=String(counts[filter]||0);button.disabled=filter!=='TODOS'&&(counts[filter]||0)===0});let visible=0;rows.forEach(row=>{const show=w2bFiltroHorario==='TODOS'||row.dataset.timeBand===w2bFiltroHorario;row.classList.toggle('w2b-time-filtered',!show);if(show)visible++});const previous=lista.querySelector('.w2b-filter-empty');if(previous)previous.remove();const first=rows.find(row=>!row.classList.contains('w2b-time-filtered'));if(first){first.classList.add('recommended');const badge=document.createElement('span');badge.className='w2b-recommended-badge';badge.textContent=w2bFiltroHorario==='TODOS'?'PRÓXIMO DISPONIBLE':'PRIMERA OPCIÓN EN '+w2bFiltroHorario;first.append(badge)}if(!visible&&rows.length){const empty=document.createElement('div');empty.className='w2b-filter-empty';empty.innerHTML='<span aria-hidden="true">⌁</span><div><b>No hay horarios en '+w2bFiltroHorario.toLowerCase()+'</b><p>Elegí otra franja para ver las opciones disponibles.</p></div><button type="button">Ver todos</button>';empty.querySelector('button')?.addEventListener('click',()=>w2bSeleccionarFiltro('TODOS'));lista.append(empty)}status.textContent=w2bFiltroHorario==='TODOS'?visible+' '+(visible===1?'horario disponible':'horarios disponibles'):visible+' '+(visible===1?'opción':'opciones')+' por la '+w2bFiltroHorario.toLowerCase()}
function w2bSeleccionarFiltro(filter:string){w2bFiltroHorario=filter;w2bActualizarFiltros()}
const w2bTimeFilters=document.getElementById('w2bTimeFilters');w2bTimeFilters?.addEventListener('click',event=>{const button=(event.target as HTMLElement).closest<HTMLButtonElement>('[data-time-filter]');if(button&&!button.disabled)w2bSeleccionarFiltro(button.dataset.timeFilter||'TODOS')});w2bTimeFilters?.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const buttons=[...w2bTimeFilters.querySelectorAll<HTMLButtonElement>('[data-time-filter]:not(:disabled)')],current=buttons.indexOf(document.activeElement as HTMLButtonElement);if(current<0)return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(current+(event.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();w2bSeleccionarFiltro(buttons[next].dataset.timeFilter||'TODOS')});
new MutationObserver(()=>w2bActualizarFiltros()).observe(el('listaHorarios'),{childList:true});
let w2bAlternativasFechaSecuencia=0;
function w2bIsoSiguiente(base:string,dias:number){const [y,m,d]=base.split('-').map(Number),fecha=new Date(y,m-1,d);fecha.setDate(fecha.getDate()+dias);fecha.setMinutes(fecha.getMinutes()-fecha.getTimezoneOffset());return fecha.toISOString().slice(0,10)}
function w2bOcultarFechasAlternativas(){const host=document.getElementById('w2bDateAlternatives');host?.classList.add('hidden');const list=document.getElementById('w2bDateAlternativesList');if(list)list.innerHTML=''}
async function w2bBuscarFechasAlternativas(items:AlternativaDisponibilidad[]){const host=document.getElementById('w2bDateAlternatives'),list=document.getElementById('w2bDateAlternativesList'),status=document.getElementById('w2bDateAlternativesStatus');if(!host||!list||!status)return;if(items.some(x=>x.horarios.length)){w2bOcultarFechasAlternativas();return}const sequence=++w2bAlternativasFechaSecuencia;host.classList.remove('hidden');host.setAttribute('aria-busy','true');status.textContent='Buscando fechas cercanas…';list.innerHTML='<div class="reserve-loading"><span></span><strong>Explorando los próximos días…</strong></div>';const fechas=Array.from({length:6},(_,i)=>w2bIsoSiguiente(estado.fecha,i+1));const resultados=await Promise.all(fechas.map(async fechaIso=>{try{const panorama=await api<PanoramaDisponibilidad>('/disponibilidad/panorama?fecha='+fechaIso,{forceRefresh:true});const canchas=estado.canchas.map(cancha=>{const d=panorama.canchas.find(x=>x.cancha.id===cancha.id);return d?{cancha,horarios:d.horarios,disponibleEseDia:d.disponibleEseDia}:{cancha,horarios:[] as Horario[],disponibleEseDia:false,error:true}});return {fecha:fechaIso,canchas}}catch{return {fecha:fechaIso,canchas:estado.canchas.map(cancha=>({cancha,horarios:[] as Horario[],disponibleEseDia:false,error:true}))}}}));if(sequence!==w2bAlternativasFechaSecuencia)return;const disponibles=resultados.map(dia=>{const opciones=dia.canchas.filter(x=>x.horarios.length);return {fecha:dia.fecha,opciones,total:opciones.reduce((n,x)=>n+x.horarios.length,0),primera:opciones.flatMap(x=>x.horarios.map(h=>({cancha:x.cancha,horario:h}))).sort((a,b)=>w2bHoraMinutos(a.horario.horaInicio)-w2bHoraMinutos(b.horario.horaInicio))[0]}}).filter(x=>x.total>0).slice(0,4);host.removeAttribute('aria-busy');if(!disponibles.length){status.textContent='Sin disponibilidad en los próximos 6 días';list.innerHTML='<div class="w2b-date-empty"><b>No encontramos horarios cercanos</b><p>Probá una fecha posterior desde el calendario.</p><button type="button" data-w2b-open-calendar>Abrir calendario</button></div>';list.querySelector<HTMLButtonElement>('[data-w2b-open-calendar]')?.addEventListener('click',()=>{paso(1);requestAnimationFrame(()=>el<HTMLButtonElement>('w2calTrigger').click())});return}status.textContent=disponibles.length+' '+(disponibles.length===1?'día con opciones':'días con opciones');list.innerHTML=disponibles.map((dia,index)=>'<button type="button" class="w2b-date-option '+(index===0?'recommended':'')+'" data-w2b-date="'+dia.fecha+'" data-w2b-court="'+dia.primera.cancha.id+'"><span><small>'+new Intl.DateTimeFormat('es-AR',{weekday:'short'}).format(new Date(dia.fecha+'T12:00:00')).replace('.','').toUpperCase()+'</small><strong>'+new Intl.DateTimeFormat('es-AR',{day:'numeric',month:'short'}).format(new Date(dia.fecha+'T12:00:00'))+'</strong></span><b>'+dia.total+' '+(dia.total===1?'horario':'horarios')+'</b><p>Desde '+hora(dia.primera.horario.horaInicio)+' · '+esc(dia.primera.cancha.nombre)+'</p>'+(index===0?'<em>PRIMERA FECHA DISPONIBLE</em>':'')+'</button>').join('');list.querySelectorAll<HTMLButtonElement>('[data-w2b-date]').forEach(button=>button.addEventListener('click',()=>{const fechaNueva=button.dataset.w2bDate||'',canchaId=Number(button.dataset.w2bCourt);const canchaNueva=estado.canchas.find(x=>x.id===canchaId);if(!fechaNueva||!canchaNueva)return;estado.fecha=fechaNueva;estado.cancha=canchaNueva;estado.horario=undefined;const input=el<HTMLInputElement>('fechaReserva');input.value=fechaNueva;sincronizarFechaVisibleReserva();renderCanchas();actualizarResumen();el<HTMLButtonElement>('buscarHorarios').click()}))}
async function resolverSesionReserva(){const inicial=estadoSesion();if(inicial.sesion||!inicial.cargando)return inicial.sesion;return new Promise<SesionGlobal|null>(resolve=>{let resuelto=false;const terminar=(sesion:SesionGlobal|null)=>{if(resuelto)return;resuelto=true;dejarDeEscuchar();removeEventListener('sesion-cliente-error',error);resolve(sesion)},error=()=>terminar(estadoSesion().sesion),dejarDeEscuchar=escucharSesion(terminar);addEventListener('sesion-cliente-error',error,{once:true})})}
async function mostrarDatos(){if(!estado.cancha||!estado.horario)return;const documento=el<HTMLInputElement>('clienteDocumento');documento.readOnly=false;documento.removeAttribute('aria-readonly');document.getElementById('documentoCuentaAyuda')?.remove();el('resumenTurno').innerHTML=`<span><small>Cancha</small><strong>${esc(estado.cancha.nombre)}</strong></span><span><small>Fecha</small><strong>${fecha(estado.fecha)}</strong></span><span><small>Horario</small><strong>${hora(estado.horario.horaInicio)} a ${hora(estado.horario.horaFin)}</strong></span><span><small>Seña</small><strong>${moneda(estado.horario.importeSenia,estado.complejo?.moneda||'ARS')}</strong></span>`;actualizarResumen();el('w2bRecoveryPanel').classList.add('hidden');paso(3);w2bIdentidad('loading');w2bActualizarRevision();w2bDatosIniciales=w2bFirmaFormulario();const sesion=await resolverSesionReserva();if(!sesion?.autenticado){w2bIdentidad('guest');w2bActualizarRevision();return}const firmaAntes=w2bFirmaFormulario();try{const p=await api<Perfil>('/cliente/perfil');if(w2bFirmaFormulario()!==firmaAntes){w2bIdentidad('account');return}w2bIdentidad('account');(['Nombre','Apellido','Documento','Telefono','Email'] as const).forEach(k=>{const dato=p[k.toLowerCase() as keyof Perfil];if(dato)el<HTMLInputElement>(`cliente${k}`).value=String(dato)});documento.readOnly=true;documento.setAttribute('aria-readonly','true');const ayuda=document.createElement('small');ayuda.id='documentoCuentaAyuda';ayuda.className='field-help';ayuda.textContent='Dato verificado de tu cuenta';documento.insertAdjacentElement('afterend',ayuda)}catch{documento.readOnly=false;w2bIdentidad('guest')}finally{w2bActualizarRevision()}}
document.querySelectorAll<HTMLButtonElement>('[data-volver]').forEach(b=>b.addEventListener('click',()=>paso(Number(b.dataset.volver))));
function limpiarErrores(){document.querySelectorAll('.field-error').forEach(x=>x.textContent='');document.querySelectorAll<HTMLElement>('.field-invalid').forEach(x=>{x.classList.remove('field-invalid');x.removeAttribute('aria-invalid')});document.getElementById('bloqueAceptarCondiciones')?.classList.remove('reserve-consent-invalid')}
class ErrorCampoReserva extends Error{constructor(public campoId:string,mensaje:string){super(mensaje);this.name='ErrorCampoReserva'}}
function altoCabeceraReserva(){const header=document.querySelector<HTMLElement>('[data-site-header]');return header?.getBoundingClientRect().height||Number.parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--header-height'))||0}
function bloqueCampoReserva(input:HTMLElement){return input.closest<HTMLElement>('label,#bloqueAceptarCondiciones')||input}
function margenSuperiorReserva(){const pasos=document.querySelector<HTMLElement>('.reserve-steps'),estadoMovil=document.getElementById('estadoPasoReservaMovil'),visible=(node:HTMLElement|null)=>node&&getComputedStyle(node).display!=='none'?Math.ceil(node.getBoundingClientRect().height):0;return altoCabeceraReserva()+visible(pasos)+visible(estadoMovil)+18}
function campoVisibleEnReserva(input:HTMLElement){const bloque=bloqueCampoReserva(input),rect=bloque.getBoundingClientRect(),margenSuperior=margenSuperiorReserva(),margenInferior=24;return rect.top>=margenSuperior&&rect.bottom<=innerHeight-margenInferior}
function enfocarCampoReserva(id:string){const input=el<HTMLInputElement>(id);input.focus({preventScroll:true});if(campoVisibleEnReserva(input))return;const bloque=bloqueCampoReserva(input),destino=Math.max(0,bloque.getBoundingClientRect().top+scrollY-margenSuperiorReserva());scrollTo({top:destino,behavior:movimientoReducidoReserva()?'auto':'smooth'})}
function errorCampo(id:string,texto:string):never{const input=el(id);input.classList.add('field-invalid');input.setAttribute('aria-invalid','true');if(id==='aceptarCondiciones')document.getElementById('bloqueAceptarCondiciones')?.classList.add('reserve-consent-invalid');document.querySelector<HTMLElement>(`[data-error="${id}"]`)!.textContent=texto;throw new ErrorCampoReserva(id,texto)}
function w2bMensajeCampo(id:string){const value=valor(id);if(id==='clienteNombre'&&!value)return 'Ingresá tu nombre.';if(id==='clienteApellido'&&!value)return 'Ingresá tu apellido.';if(id==='clienteDocumento'&&!/^\d{7,10}$/.test(value.replace(/\D/g,'')))return 'Ingresá entre 7 y 10 números.';if(id==='clienteTelefono'&&!/^[0-9+()\-\s]{6,30}$/.test(value))return 'Ingresá un teléfono válido.';if(id==='clienteEmail'&&value&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value))return 'Ingresá un correo válido.';return ''}
function w2bValidarCampoProgresivo(input:HTMLInputElement|HTMLTextAreaElement,forzar=false){if(input.readOnly||input.type==='hidden')return true;const touched=input.dataset.touched==='true'||forzar;if(!touched)return true;const text=w2bMensajeCampo(input.id),error=document.querySelector<HTMLElement>('[data-error="'+input.id+'"]');input.classList.toggle('field-invalid',!!text);if(text)input.setAttribute('aria-invalid','true');else input.removeAttribute('aria-invalid');if(error){error.textContent=text;error.id='error-'+input.id;input.setAttribute('aria-describedby',error.id)}return !text}
const w2bCampos=[...document.querySelectorAll<HTMLInputElement|HTMLTextAreaElement>('#formReserva input:not([type=hidden]),#formReserva textarea')];w2bCampos.forEach(input=>{input.addEventListener('input',()=>{input.classList.remove('field-invalid');input.removeAttribute('aria-invalid');const error=document.querySelector<HTMLElement>('[data-error="'+input.id+'"]');if(error)error.textContent=''});input.addEventListener('blur',()=>{input.dataset.touched='true';w2bValidarCampoProgresivo(input);w2bActualizarRevision()})});
function w2bMostrarRecuperacion(texto:string){const panel=el('w2bRecoveryPanel');el('w2bRecoveryCopy').textContent=texto;panel.classList.remove('hidden');panel.focus?.({preventScroll:true});panel.scrollIntoView({behavior:movimientoReducidoReserva()?'auto':'smooth',block:'center'})}
el('w2bRecoveryAction').addEventListener('click',()=>{el('w2bRecoveryPanel').classList.add('hidden');paso(2);requestAnimationFrame(()=>el('listaHorarios').scrollIntoView({behavior:movimientoReducidoReserva()?'auto':'smooth',block:'start'}))});
function validar(){limpiarErrores();w2bCampos.forEach(input=>{input.dataset.touched='true';w2bValidarCampoProgresivo(input,true)});if(!valor('clienteNombre'))errorCampo('clienteNombre','Ingresá tu nombre.');if(!valor('clienteApellido'))errorCampo('clienteApellido','Ingresá tu apellido.');if(!/^\d{7,10}$/.test(valor('clienteDocumento').replace(/\D/g,'')))errorCampo('clienteDocumento','Ingresá entre 7 y 10 números.');if(!/^[0-9+()\-\s]{6,30}$/.test(valor('clienteTelefono')))errorCampo('clienteTelefono','Ingresá un teléfono válido.');if(valor('clienteEmail')&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(valor('clienteEmail')))errorCampo('clienteEmail','Ingresá un correo válido.');if(!el<HTMLInputElement>('aceptarCondiciones').checked)errorCampo('aceptarCondiciones','Aceptá la condición de reserva temporal.')}
el<HTMLInputElement>('aceptarCondiciones').addEventListener('change',ev=>{const input=ev.currentTarget as HTMLInputElement;if(!input.checked)return;input.classList.remove('field-invalid');document.getElementById('bloqueAceptarCondiciones')?.classList.remove('reserve-consent-invalid');const error=document.querySelector<HTMLElement>('[data-error="aceptarCondiciones"]');if(error)error.textContent='';if(document.activeElement?.id==='mensajeReserva')input.focus({preventScroll:true})});
let contadorConfirmacionReserva=0;
function w2cDetenerTemporizadoresPrincipales(){if(contadorConfirmacionReserva){clearInterval(contadorConfirmacionReserva);contadorConfirmacionReserva=0}if(w2cPaymentChoiceTimer){clearInterval(w2cPaymentChoiceTimer);w2cPaymentChoiceTimer=0}}
function textoCopiado(id:string,valor:string,ok:string){const boton=document.getElementById(id) as HTMLButtonElement|null;if(!boton)return;boton.addEventListener('click',async()=>{const original=boton.textContent||'';try{await navigator.clipboard.writeText(valor);boton.textContent=ok;boton.classList.add('copiado')}catch{boton.textContent='No se pudo copiar';boton.classList.add('error-copia')}setTimeout(()=>{boton.textContent=original;boton.classList.remove('copiado','error-copia')},1600)})}
function relojConfirmacion(total:number){const s=Math.max(0,Math.floor(total)),m=Math.floor(s/60),r=s%60;return String(m).padStart(2,'0')+':'+String(r).padStart(2,'0')}
function sincronizarLateralConfirmacion(restante:number,importe:number,monedaCodigo:string){const proteccion=document.getElementById('datoProteccionReserva'),etiquetaProteccion=document.getElementById('etiquetaProteccionReserva'),senia=document.getElementById('datoSeniaReserva'),etiquetaSenia=document.getElementById('etiquetaSeniaReserva');if(proteccion)proteccion.textContent=restante>0?relojConfirmacion(restante):'Vencida';if(etiquetaProteccion)etiquetaProteccion.textContent=restante>0?'Tiempo restante':'Protección finalizada';if(senia)senia.textContent=moneda(importe,monedaCodigo);if(etiquetaSenia)etiquetaSenia.textContent='Importe a acreditar';const estadoLateral=document.getElementById('estadoReservaLateral'),resumen=document.querySelector<HTMLElement>('.w2-booking-summary');if(estadoLateral){estadoLateral.textContent=restante>0?'Esperando acreditación':'Protección finalizada';estadoLateral.classList.remove('hidden');estadoLateral.classList.toggle('expired',restante<=0)}resumen?.classList.add('confirmation-live')}
function bloquearPasosConfirmados(){document.querySelectorAll<HTMLElement>('[data-paso-indicador]').forEach(x=>{x.classList.remove('navegable');x.tabIndex=-1;x.setAttribute('role','presentation');x.setAttribute('aria-disabled','true')})}
function iniciarProteccionConfirmacion(segundos:number,importe:number,monedaCodigo:string){if(contadorConfirmacionReserva)clearInterval(contadorConfirmacionReserva);let restante=Math.max(0,segundos);const actualizar=()=>{const host=document.querySelector<HTMLElement>('.reserve-confirmation-shell'),valor=document.getElementById('contadorReserva'),estadoTexto=document.getElementById('estadoProteccionReserva');if(valor)valor.textContent=relojConfirmacion(restante);sincronizarLateralConfirmacion(restante,importe,monedaCodigo);host?.classList.toggle('urgent',restante>0&&restante<=120);if(restante<=0){if(valor)valor.textContent='Vencida';if(estadoTexto)estadoTexto.textContent='La protección terminó. Consultá el estado real antes de volver a reservar.';host?.classList.add('expired');document.getElementById('bloquePagoReserva')?.classList.add('expired');document.getElementById('enviarComprobanteReserva')?.setAttribute('aria-disabled','true');if(contadorConfirmacionReserva)clearInterval(contadorConfirmacionReserva);return}restante--};actualizar();contadorConfirmacionReserva=window.setInterval(actualizar,1000)}
function whatsappComprobante(complejo:Complejo|undefined,creada:SolicitudReservaCreada,importe:number){const telefono=String(complejo?.whatsapp||complejo?.telefono||'').replace(/\D/g,'');if(!telefono)return '';const texto='Hola, envío el comprobante de la seña de '+moneda(importe,creada.moneda)+' para la reserva '+creada.codigoSeguimiento+' · '+creada.cancha+' · '+fecha(creada.fecha)+' · '+hora(creada.horaInicio)+'.';return 'https://wa.me/'+telefono+'?text='+encodeURIComponent(texto)}
function bloqueTransferencia(complejo:Complejo|undefined,orden:OrdenPagoPublica,creada:SolicitudReservaCreada){if(!complejo?.pagoTransferenciaDisponible||!orden.puedeInformarTransferencia)return '<section id="bloquePagoReserva" class="reserve-payment-card unavailable"><p class="w2-kicker">Próximo paso</p><h3>Consultá los medios disponibles</h3><p>Podés ver el estado actualizado y las opciones habilitadas desde Mi cuenta.</p></section>';const importe=orden.importe||creada.importeSenia,whatsapp=whatsappComprobante(complejo,creada,importe);return '<section id="bloquePagoReserva" class="reserve-payment-card manual"><div class="reserve-payment-card-head"><div><p class="w2-kicker">Cómo confirmar</p><h3>Completá la seña en tres pasos</h3></div><span>VERIFICACIÓN MANUAL</span></div><ol class="reserve-payment-steps"><li><i>1</i><span><small>COPIÁ EL ALIAS</small><b>'+esc(complejo.pagoAlias||'-')+'</b></span><button id="copiarAliasReserva" type="button">Copiar alias</button></li><li><i>2</i><span><small>TRANSFERÍ EL IMPORTE EXACTO</small><b>'+moneda(importe,orden.moneda||creada.moneda)+'</b></span><button id="copiarImporteReserva" type="button">Copiar importe</button></li><li><i>3</i><span><small>ENVIÁ EL COMPROBANTE</small><b>El mensaje incluye el código de seguimiento</b></span>'+(whatsapp?'<a id="enviarComprobanteReserva" href="'+esc(whatsapp)+'" target="_blank" rel="noopener noreferrer">Enviar comprobante por WhatsApp</a>':'<em>WhatsApp no configurado</em>')+'</li></ol><dl class="w2c-bank-details"><div><dt>Titular de la cuenta</dt><dd>'+esc(complejo.pagoTitular||'-')+'</dd></div><div><dt>Entidad receptora</dt><dd>'+esc(complejo.pagoEntidad||'-')+'</dd></div><div><dt>Modalidad</dt><dd>Transferencia manual</dd></div></dl><p class="reserve-payment-note"><b>Pendiente de verificación.</b> Después de enviar el comprobante, el complejo revisará la acreditación. Podés seguir el estado desde Mi cuenta.</p></section>'}
function renderConfirmacion(creada:SolicitudReservaCreada,orden:OrdenPagoPublica){w2cDetenerTemporizadoresPrincipales();const segundos=w2cSegundosProteccion(creada,orden.segundosRestantes);const manual=orden.estado==='ESPERANDO_VERIFICACION'||orden.metodo==='TRANSFERENCIA_MANUAL';w2cCompletarResumenDesdeCreada(creada);w2cAplicarCabeceraPaso4('protected');w2cActualizarResumenEstado(creada,'protected',orden.metodo);el('confirmacionReserva').innerHTML='<div class="reserve-confirmation-shell '+(manual?'manual':'')+'"><section class="reserve-confirmation-status"><div><span class="reserve-live-dot"></span><small>PROTECCIÓN ACTIVA</small><h3 id="estadoProteccionReserva">La cancha está retenida mientras completás la seña.</h3></div><span class="reserve-confirmation-timer"><small>TIEMPO RESTANTE</small><strong id="contadorReserva">'+relojConfirmacion(segundos)+'</strong></span></section><section class="reserve-confirmation-overview"><article><small>CANCHA</small><strong>'+esc(creada.cancha)+'</strong><span>'+fecha(creada.fecha)+' · '+hora(creada.horaInicio)+' a '+hora(creada.horaFin)+'</span></article><article><small>IMPORTE DEL TURNO</small><strong>'+moneda(creada.precioTotal,creada.moneda)+'</strong><span>Seña '+moneda(orden.importe||creada.importeSenia,orden.moneda||creada.moneda)+' · Saldo '+moneda(Math.max(0,creada.precioTotal-(orden.importe||creada.importeSenia)),orden.moneda||creada.moneda)+'</span></article></section>'+bloqueTransferencia(estado.complejo,orden,creada)+'<section class="reserve-confirmation-tracking"><div><small>CÓDIGO DE SEGUIMIENTO</small><strong title="'+esc(creada.codigoSeguimiento)+'">'+esc(creada.codigoSeguimiento.slice(0,8).toUpperCase()+'…'+creada.codigoSeguimiento.slice(-4).toUpperCase())+'</strong><span>Guardalo para consultar la reserva en cualquier momento.</span></div><button id="copiarCodigoReserva" type="button">Copiar código</button></section><p class="reserve-confirmation-honesty"><span aria-hidden="true">i</span><span><b>La reserva todavía no está confirmada.</b> '+(manual?'El complejo verificará la transferencia y acreditará la seña manualmente.':'El sistema confirmará el turno cuando Mercado Pago informe la acreditación.')+'</span></p></div>';bloquearPasosConfirmados();iniciarProteccionConfirmacion(segundos,orden.importe||creada.importeSenia,orden.moneda||creada.moneda);textoCopiado('copiarCodigoReserva',creada.codigoSeguimiento,'Código copiado ✓');textoCopiado('copiarAliasReserva',estado.complejo?.pagoAlias||'','Alias copiado ✓');textoCopiado('copiarImporteReserva',String(orden.importe||creada.importeSenia),'Importe copiado ✓')}
async function crearOrdenReserva(reservaId:number,metodo:'TRANSFERENCIA_MANUAL'|'PAGO_ONLINE',codigo?:string){const ruta=codigo?'/solicitudes/'+encodeURIComponent(codigo)+'/pago':'/cliente/reservas/'+reservaId+'/pago';return api<OrdenPagoPublica>(ruta,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({metodo})})}
function checkoutSeguro(url?:string|null){if(!url)return false;try{const u=new URL(url),host=u.hostname.toLowerCase();return u.protocol==='https:'&&(['mercadopago.com','mercadopago.com.ar'].some(d=>host===d||host.endsWith('.'+d)))}catch{return false}}
type W2cContextoPago={creada:SolicitudReservaCreada;cancha?:Cancha;horario?:Horario;fecha?:string};
function w2cSegundosProteccion(creada:SolicitudReservaCreada,segundos?:number|null){const limite=Math.max(60,(creada.minutosParaPagar||10)*60),directo=Number(segundos);if(Number.isFinite(directo)&&directo>=0)return Math.min(Math.floor(directo),limite);const calculado=Math.floor((new Date(creada.vencimiento).getTime()-Date.now())/1000);return Number.isFinite(calculado)&&calculado>=0&&calculado<=limite+60?calculado:limite}
