const w2bPaymentStatusHost=document.getElementById('estadoEleccionPago');if(w2bPaymentStatusHost)w2bPaymentStatusObserver.observe(w2bPaymentStatusHost,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});



/* F2F1 - convergencia posterior a la eleccion del medio */
const mejorarEstadosPagoElegidos=()=>{
  const root=document.querySelector<HTMLElement>('[data-panel="4"]');
  if(!root)return;
  const retorno=root.querySelector<HTMLElement>('.w2c-return');
  if(retorno){
    const stateLabel=retorno.querySelector<HTMLElement>('.w2c-return-metrics span:first-child small,.w2c-return-metrics span:first-child b');
    if(stateLabel&&/ESTADO DEL SISTEMA/i.test(stateLabel.textContent||''))stateLabel.textContent='ESTADO DEL PAGO';
  }
  const manualPanel=root.querySelector<HTMLElement>('.w2c-transfer,.w2c-manual-payment,[data-transfer-panel]');
  if(manualPanel){
    manualPanel.classList.add('w2f-transfer-refined');
    const entities=[...manualPanel.querySelectorAll<HTMLElement>('small,b,strong')];
    for(const el of entities){if(/^ENTIDAD RECEPTORA$/i.test((el.textContent||'').trim()))el.textContent='CUENTA RECEPTORA'}
    const rows=[...manualPanel.querySelectorAll<HTMLElement>('.w2c-transfer-step,.w2c-payment-step,.reserve-payment-step')];
    if(rows[2])rows[2].classList.add('w2f-final-step');
    const tracking=manualPanel.querySelector<HTMLElement>('.w2c-tracking,.reserve-confirmation-tracking,[data-tracking-code]');
    if(tracking)tracking.classList.add('w2f-tracking-integrated');
    for(const button of manualPanel.querySelectorAll<HTMLButtonElement>('button')){
      if(/^Copiar /i.test(button.textContent||'')){button.classList.add('w2f-copy-action');if(!button.dataset.w2fCopy){button.dataset.w2fCopy='ready';button.addEventListener('click',()=>{const original=button.textContent||'Copiar';button.dataset.copyState='done';button.textContent=original.replace(/^Copiar/i,'Copiado');setTimeout(()=>{button.textContent=original;delete button.dataset.copyState},1800)})}}
    }
  }
};
const observarEstadosPago=()=>{mejorarEstadosPagoElegidos();const panel=document.querySelector('[data-panel="4"]');if(panel&&!panel.hasAttribute('data-w2f-observed')){panel.setAttribute('data-w2f-observed','true');new MutationObserver(mejorarEstadosPagoElegidos).observe(panel,{childList:true,subtree:true})}};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',observarEstadosPago,{once:true});else observarEstadosPago();


/* F2F1A - transferencia funcional y refinamiento autoritativo */
const refinarTransferenciaAutoritativa=()=>{
 const panel=document.querySelector<HTMLElement>('[data-panel="4"]');if(!panel)return;
 const transferShell=panel.querySelector<HTMLElement>('.reserve-payment-steps')?.closest<HTMLElement>('.reserve-confirmation-shell,#bloquePagoReserva,.reserve-confirmation-panel');
 if(transferShell)transferShell.classList.add('w2f-transfer-open');
 const rows=[...panel.querySelectorAll<HTMLElement>('.reserve-payment-steps>*,.w2c-transfer-step,.w2c-payment-step')];
 if(rows.length>=3)rows[2].classList.add('w2f-final-step');
 for(const button of panel.querySelectorAll<HTMLButtonElement>('button')){
   const label=(button.textContent||'').trim();
   if(/^Copiar (alias|importe|código|codigo)/i.test(label)){
     button.classList.add('w2f-copy-action');
     if(!button.dataset.w2fCopyBound){button.dataset.w2fCopyBound='true';button.addEventListener('click',()=>{const original=button.dataset.w2fOriginal||label;button.dataset.w2fOriginal=original;button.dataset.copyState='done';button.textContent=original.replace(/^Copiar/i,'Copiado');window.setTimeout(()=>{button.textContent=original;delete button.dataset.copyState},1800)})}
   }
 }
 // En el retorno online se reutiliza siempre el control real de transferencia y su listener original.
 const returnActions=panel.querySelector<HTMLElement>('.w2c-return-actions');
 if(returnActions){
   const candidates=[...panel.querySelectorAll<HTMLElement>('[data-w2c-manual]')];
   const real=candidates.find(x=>!x.classList.contains('w2c-return-secondary'))||null;
   for(const fake of candidates.filter(x=>x.classList.contains('w2c-return-secondary')))fake.remove();
   if(real&&!returnActions.contains(real)){const account=returnActions.querySelector('.w2c-account-action');returnActions.insertBefore(real,account||null)}
 }
};
const iniciarRefinamientoTransferencia=()=>{refinarTransferenciaAutoritativa();const p=document.querySelector('[data-panel="4"]');if(p&&!p.hasAttribute('data-w2f1a-observed')){p.setAttribute('data-w2f1a-observed','true');new MutationObserver(refinarTransferenciaAutoritativa).observe(p,{childList:true,subtree:true})}};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',iniciarRefinamientoTransferencia,{once:true});else iniciarRefinamientoTransferencia();


/* F2F1B - convergencia estable y feedback delegado */
const instalarFeedbackCopiaEstable=()=>{
 const panel=document.querySelector<HTMLElement>('[data-panel="4"]');if(!panel||panel.dataset.w2f1bCopy==='true')return;panel.dataset.w2f1bCopy='true';
 panel.addEventListener('click',event=>{
   const target=(event.target as HTMLElement).closest<HTMLButtonElement>('#copiarAliasReserva,#copiarImporteReserva,[data-copy-tracking]');if(!target)return;
   const original=target.dataset.w2fOriginal||target.textContent?.trim()||'Copiar';target.dataset.w2fOriginal=original;
   window.setTimeout(()=>{if(!target.isConnected)return;target.dataset.copyState='done';target.setAttribute('aria-label',original.replace(/^Copiar/i,'Copiado'));window.setTimeout(()=>{if(!target.isConnected)return;delete target.dataset.copyState;target.setAttribute('aria-label',original)},1800)},0);
 },true);
};
const asegurarMediosPago=()=>{
 const panel=document.querySelector<HTMLElement>('[data-panel="4"]');if(!panel)return;instalarFeedbackCopiaEstable();
 const chooser=panel.querySelector<HTMLElement>('.reserve-payment-choice');
 if(chooser&&!chooser.querySelector('[data-pay-manual]')){const detached=panel.querySelector<HTMLElement>('[data-w2c-manual]');if(detached&&!detached.closest('.w2c-return-actions'))chooser.querySelector('.reserve-payment-methods,div:has([data-pay-online])')?.append(detached)}
};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',asegurarMediosPago,{once:true});else asegurarMediosPago();


/* F2F1D - estado lateral de reintento autoritativo */
const sincronizarReintentoLateral=()=>{
 const panel=document.querySelector<HTMLElement>('[data-panel="4"]');if(!panel)return;
 const choiceStatus=panel.querySelector<HTMLElement>('#estadoEleccionPago');
 const sideStatus=document.querySelector<HTMLElement>('#estadoReservaLateral');
 if(!choiceStatus||!sideStatus)return;
 const failed=choiceStatus.classList.contains('error')&&/No pudimos preparar|Seleccioná nuevamente|Intentar nuevamente/i.test(choiceStatus.textContent||'');
 if(failed){sideStatus.textContent='Reintento disponible';sideStatus.dataset.paymentUiState='retry'}
 else if(sideStatus.dataset.paymentUiState==='retry'&&!choiceStatus.classList.contains('error'))delete sideStatus.dataset.paymentUiState;
};
const iniciarSincronizacionReintento=()=>{
 const panel=document.querySelector<HTMLElement>('[data-panel="4"]');if(!panel)return;sincronizarReintentoLateral();
 const target=panel.querySelector('#estadoEleccionPago')||panel;
 if(!(target as HTMLElement).dataset.w2f1dObserved){(target as HTMLElement).dataset.w2f1dObserved='true';new MutationObserver(sincronizarReintentoLateral).observe(target,{subtree:true,childList:true,attributes:true,attributeFilter:['class']})}
};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',iniciarSincronizacionReintento,{once:true});else iniciarSincronizacionReintento();
